use super::*;
use crate::position::AccountPosition;
use crate::fees::FeeKind;
use crate::transfer::TransferOffer;

pub(crate) fn gather_evidence(a: &AccountPosition, input: &NegotiationInput) -> Vec<Evidence> {
    let mut out: Vec<Evidence> = Vec::new();

    if let Some((_, tenure)) = input.tenure_months.iter().find(|(k, _)| *k == a.account) {
        out.push(Evidence {
            claim: format!("the account has been open {tenure} month(s)"),
            // Under a year is not tenure, it is a trial period, and saying it out loud helps nobody.
            strength: if *tenure >= 36 { Strength::Strong } else if *tenure >= 12 { Strength::Moderate } else { Strength::Weak },
            source: "months between the first and last transaction observed on this account".to_string(),
        });
    }

    if let Some(fees) = input.fees {
        let mine: Vec<&crate::fees::Fee> = fees.fees.iter().filter(|f| f.account == a.account).collect();
        let late: Vec<&&crate::fees::Fee> = mine.iter().filter(|f| f.kind == FeeKind::Late || f.kind == FeeKind::Nsf).collect();
        if late.is_empty() {
            // THE STRONGEST SINGLE CARD, and it is the one people forget they hold.
            out.push(Evidence {
                claim: "no late or returned-payment fee appears anywhere in the statements held".to_string(),
                strength: Strength::Strong,
                source: "the fee audit over every ingested statement".to_string(),
            });
        } else {
            let mut dates: Vec<&str> = late.iter().map(|f| f.date.as_str()).collect();
            dates.sort();
            out.push(Evidence {
                claim: format!("{} late or returned-payment fee(s) appear, the most recent on {}", late.len(), dates.last().copied().unwrap_or("")),
                strength: Strength::Weak,
                source: "the fee audit".to_string(),
            });
        }
        let interest: i64 = mine.iter().filter(|f| f.kind == FeeKind::Interest).map(|f| f.amount.minor.abs()).sum();
        if interest > 0 {
            // Concrete, and THEIR OWN NUMBER. "I have paid you X" is a harder sentence to wave away
            // than "your rate is high".
            out.push(Evidence {
                claim: format!("{interest} minor units of interest have been paid to this account in the statements held"),
                strength: Strength::Strong,
                source: "the fee audit, interest rows only".to_string(),
            });
        }
    }

    let mut better: Vec<&TransferOffer> = input
        .offers
        .iter()
        .filter(|o| o.institution != a.institution && o.promo_apr < a.apr.unwrap_or(f64::INFINITY))
        .collect();
    better.sort_by(|x, y| x.promo_apr.partial_cmp(&y.promo_apr).unwrap_or(std::cmp::Ordering::Equal));
    if let Some(b) = better.first() {
        let expires = b.offer_expires.as_ref().map(|e| format!(", expiring {e}")).unwrap_or_default();
        out.push(Evidence {
            claim: format!("{} is offering {} for {} months{expires}", b.institution, pct(b.promo_apr), b.promo_months),
            strength: Strength::Strong,
            source: "an offer supplied to this analysis — name it only if it is real and you would take it".to_string(),
        });
    }

    if let Some(u) = a.utilisation {
        out.push(Evidence {
            claim: if u <= 0.3 {
                format!("this line is only {}% used, which is what a low-risk customer looks like", (u * 100.0).round())
            } else {
                format!("this line is {}% used, which is what a customer worth retaining looks like", (u * 100.0).round())
            },
            strength: if u <= 0.3 { Strength::Moderate } else { Strength::Weak },
            source: "the position's utilisation for this account".to_string(),
        });
    }

    out
}
